require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../services/overtime_workflow.php';
$a=ed_start($conn);ed_personal_scope($conn,$a);if(!ac_table($conn,'overtime_requests'))ac_fail('Migrasi lembur belum tersedia.',503);
if($_SERVER['REQUEST_METHOD']==='GET'){$where=[];$params=[];if(!empty($_GET['employee_id'])){$where[]='o.employee_id=?';$params[]=ac_id($_GET['employee_id']);}if(!empty($_GET['status'])){$where[]='o.status=?';$params[]=ac_text($_GET['status'],'Status',30);}ed_respond(200,['status'=>'success','data'=>ac_rows($conn,'SELECT o.*,e.full_name AS employee_name,u.email AS approved_by_email FROM overtime_requests o JOIN employees e ON e.id=o.employee_id LEFT JOIN users u ON u.id=o.approved_by'.($where?' WHERE '.implode(' AND ',$where):'').' ORDER BY o.date DESC,o.id DESC',$params)]);}
$d=json_decode(file_get_contents('php://input'),true);if(!is_array($d))ac_fail('Data tidak valid.');$result=ot_mutate($conn,$a,$d,$_SERVER['REQUEST_METHOD']);ed_respond(200,['status'=>'success','message'=>'Request lembur tersimpan.','data'=>$result,'id'=>$result['id']]);
